#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define SOURCE_FLAG 0x80000000u

static int compare_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int x[2000], y[2000];
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }

    size_t edge_count = (size_t)n * n;
    uint64_t *edges = malloc(edge_count * sizeof(uint64_t));
    int *best = calloc((size_t)n, sizeof(int));

    if (edges == NULL || best == NULL) {
        free(edges);
        free(best);
        return 0;
    }

    size_t count = 0;

    for (int j = 0; j < n; j++) {
        uint32_t w = (uint32_t)(x[j] * x[j] + y[j] * y[j]);
        uint32_t code = SOURCE_FLAG | (uint32_t)j;
        edges[count++] = ((uint64_t)(UINT32_MAX - w) << 32) | code;
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int dx = x[i] - x[j];
            int dy = y[i] - y[j];
            uint32_t w = (uint32_t)(dx * dx + dy * dy);
            uint32_t code = (uint32_t)i * (uint32_t)n + (uint32_t)j;
            edges[count++] = ((uint64_t)(UINT32_MAX - w) << 32) | code;
        }
    }

    qsort(edges, count, sizeof(uint64_t), compare_u64);

    int answer = 0;
    size_t left = 0;

    while (left < count) {
        uint32_t key = (uint32_t)(edges[left] >> 32);
        size_t right = left + 1;
        while (right < count && (uint32_t)(edges[right] >> 32) == key) {
            right++;
        }

        for (size_t k = left; k < right; k++) {
            uint32_t code = (uint32_t)edges[k];
            int value;

            if (code & SOURCE_FLAG) {
                value = 1;
            } else {
                int from = (int)(code / (uint32_t)n);
                value = best[from] ? best[from] + 1 : 0;
            }

            if (value > answer) answer = value;
        }

        for (size_t k = left; k < right; k++) {
            uint32_t code = (uint32_t)edges[k];
            int to, value;

            if (code & SOURCE_FLAG) {
                to = (int)(code & ~SOURCE_FLAG);
                value = 1;
            } else {
                int from = (int)(code / (uint32_t)n);
                to = (int)(code % (uint32_t)n);
                value = best[from] ? best[from] + 1 : 0;
            }

            if (value > best[to]) best[to] = value;
        }

        left = right;
    }

    printf("%d\n", answer);

    free(edges);
    free(best);
    return 0;
}
